\textbf{Step 1. Construction of the interpolation.} As in \Cref{subsubsec: 1D}, we interpolate between \(\mu\) and \(\widetilde\mu_\varepsilon\) by letting the variance of the normal perturbation grow from \(0\) to \(\varepsilon\): for \(t\in[0,1]\), we let \(\mu_{t,\varepsilon}\stackrel{\text{def.}}{=}\widetilde\mu_{t^2\varepsilon}\) be the marginal of the normal perturbation \(\widetilde\gamma_{t^2\varepsilon}\), with the convention \(\widetilde\gamma_0\stackrel{\text{def.}}{=}\overline\gamma\). In other words, by \eqref{eq: recovery sequence with wrong marginals 1}, for every \(\phi\in C^1(M)\),
\begin{equation}
\label{eq: interpolation-global}
\int_M\phi\mathop{}\mathopen{}\mathrm{d}\mu_{t,\varepsilon}
=\int_\Sigma\int_{\mathbb{B}_R}\phi\bigl(\operatorname{\mathrm{proj}}_M(\Phi(z,t\sqrt\varepsilon s))\bigr)K(z,s)\mathop{}\mathopen{}\mathrm{d} s\mathop{}\mathopen{}\mathrm{d}\overline\gamma(z),
\end{equation}
so that \(\mu_{0,\varepsilon}=\mu\) and \(\mu_{1,\varepsilon}=\widetilde\mu_\varepsilon\).

To compute \(\mu_{t,\varepsilon}\), we use the charts \(\alpha_j\). For \(j\in J\) and \(x\in V_j\), we write
\[
A_j(x)\stackrel{\text{def.}}{=} A(\alpha_j(x)),
\qquad
K_j(x,s)\stackrel{\text{def.}}{=} K(\alpha_j(x),s).
\]
Inserting \(\sum_{j\in J}\chi_j=1\) in \eqref{eq: interpolation-global}, then changing variables \(z=\alpha_j(x)\) in each term by the area formula, and using \(\operatorname{\mathrm{proj}}_M(\Phi(\alpha_j(x),t\sqrt\varepsilon s))=x+t\sqrt\varepsilon A_j(x)s\), we get
\begin{align*}
\int_M\phi\mathop{}\mathopen{}\mathrm{d}\mu_{t,\varepsilon}
&=\sum_{j\in J}\int_{U_j}\int_{\mathbb{B}_R}\chi_j(z)\,\phi\bigl(\operatorname{\mathrm{proj}}_M(\Phi(z,t\sqrt\varepsilon s))\bigr)K(z,s)\mathop{}\mathopen{}\mathrm{d} s\,\overline\rho(z)\mathop{}\mathopen{}\mathrm{d}\mathcal H^d(z)
\\
&=\sum_{j\in J}\int_{V_j}\int_{\mathbb{B}_R}\phi\bigl(x+t\sqrt\varepsilon A_j(x)s\bigr)K_j(x,s)\mathop{}\mathopen{}\mathrm{d} s
\\
&\hspace{4cm}\times\chi_j(\alpha_j(x))\,\overline\rho(\alpha_j(x))\,\mathcal J_{\alpha_j}(x)\mathop{}\mathopen{}\mathrm{d}\operatorname{vol}_M(x)
\\
&=\sum_{j\in J}\int_{V_j}\int_{\mathbb{B}_R}\phi\bigl(\zeta^j_{\varepsilon,s,t}(x)\bigr)\,\rho_j(x)K_j(x,s)\mathop{}\mathopen{}\mathrm{d} s\mathop{}\mathopen{}\mathrm{d}\operatorname{vol}_M(x),
\end{align*}
where, for \(s\in\mathbb{B}_R\), \(t\in[0,1]\) and \(x\in V_j\), we have set
\[
\zeta_{\varepsilon,s,t}^j(x) \stackrel{\text{def.}}{=} x + t \sqrt{\varepsilon }A_j(x)s,
\qquad
\rho_j(x)\stackrel{\text{def.}}{=}\chi_j(\alpha_j(x))\,\overline\rho(\alpha_j(x))\,\mathcal J_{\alpha_j}(x).
\]
Here \(\zeta^j_{\varepsilon,s,t}(x)\) is the projection onto \(M\) of the point \(\Phi(\alpha_j(x),t\sqrt\varepsilon s)\), obtained by moving the point \(\alpha_j(x)\in\Sigma\) lying above \(x\) in the normal direction (see \Cref{fig: normal-perturbation}), and \(\rho_j\) is the density, with respect to \(\operatorname{vol}_M\), of the partial marginal \((\operatorname{\mathrm{proj}}_M)_\#(\chi_j\overline\gamma)\), concentrated on \(V_j\). Hence
\begin{equation}
\label{eq: interpolation-charts}
\mu_{t,\varepsilon} = \sum_{j\in J} \mu_{t,\varepsilon}^j,
\qquad
\mu_{t,\varepsilon}^j\stackrel{\text{def.}}{=}\bigl((s,x)\mapsto\zeta^j_{\varepsilon,s,t}(x)\bigr)_\#\bigl(\rho_j(x)K_j(x,s)\mathop{}\mathopen{}\mathrm{d} s\mathop{}\mathopen{}\mathrm{d}\operatorname{vol}_M(x)\bigr).
\end{equation}
Equivalently, \(\mu_{t,\varepsilon}^j=\int_{\mathbb{B}_R}(\zeta_{\varepsilon,s,t}^j)_{\#}(\rho_jK_j(\cdot,s)\operatorname{vol}_M)\mathop{}\mathopen{}\mathrm{d} s\), which is the form used below.

\textbf{Step 2. Construction of the flux.} For every \(\phi\in C^1(M)\), by \eqref{eq: interpolation-charts},
\begin{align*}
\frac{\mathop{}\mathopen{}\mathrm{d}}{\mathop{}\mathopen{}\mathrm{d} t}\int_M \phi\mathop{}\mathopen{}\mathrm{d}\mu_{t,\varepsilon}
&=\frac{\mathop{}\mathopen{}\mathrm{d}}{\mathop{}\mathopen{}\mathrm{d} t}\sum_{j\in J}\int_{V_j} \int_{\mathbb{B}_R}\phi(\zeta_{\varepsilon,s,t}^j(x))\rho_j(x)K_j(x,s) \mathop{}\mathopen{}\mathrm{d} s \mathop{}\mathopen{}\mathrm{d} \operatorname{vol}_M(x) 
\\
&=\sum_{j\in J}\int_{V_j} \int_{\mathbb{B}_R} \big\langle \nabla \phi(\zeta_{\varepsilon,s,t}^j(x)), \partial_t\zeta_{\varepsilon,s,t}^j (x)\big\rangle \rho_j(x)K_j(x,s) \mathop{}\mathopen{}\mathrm{d} s \mathop{}\mathopen{}\mathrm{d} \operatorname{vol}_M(x)
\\
&=\sum_{j\in J}\int_{V_j} \int_{\mathbb{B}_R} \sqrt{\varepsilon}\big\langle \nabla \phi(\zeta_{\varepsilon,s,t}^j(x)), A_j(x)s  \big\rangle \rho_j(x)K_j(x,s) \mathop{}\mathopen{}\mathrm{d} s \mathop{}\mathopen{}\mathrm{d} \operatorname{vol}_M(x)
\\
&=
\int_M
\left\langle \nabla \phi,\mathop{}\mathopen{}\mathrm{d}\operatorname{\mathfrak m_{t,\varepsilon}}\right\rangle,
\end{align*}
where the differentiation under the integral sign is justified since \(\nabla\phi\) is bounded and \(|\partial_t\zeta^j_{\varepsilon,s,t}(x)|=\sqrt\varepsilon|A_j(x)s|\leq\sqrt\varepsilon R\), and where the flux \(\operatorname{\mathfrak m_{t,\varepsilon}}\in \mathcal M(M;TM)\) is the vector measure defined by
\[\operatorname{\mathfrak m_{t,\varepsilon}} \stackrel{\text{def.}}{=} \sqrt{\varepsilon}\sum_{j\in J} \int_{\mathbb{B}_R} (\zeta_{\varepsilon,s,t}^j)_{\#}\left(\rho_jK_j(\cdot,s)A_js\, \operatorname{vol}_M\right) \mathop{}\mathopen{}\mathrm{d} s. \]
Integrating in time against a test function in
\(C_c^1((0,1))\) yields
\[
\partial_t\mu_{t,\varepsilon}
+
\operatorname{div}\operatorname{\mathfrak m_{t,\varepsilon}}
=0
\qquad\text{in }\mathcal D'((0,1)\times M).
\]

\textbf{Step 3. Gaussian symmetry.} As in \Cref{subsubsec: 1D}, the flux depends linearly on the densities \(\rho_j\). For \(j\in J\), \(s\in\mathbb{B}_R\) and \(f\in L^1(V_j)\), let
\[
F_{j,s}[f](x) \stackrel{\text{def.}}{=}
\begin{cases}
f(x)K_j(x,s)A_j(x)s,
& x\in V_j,
\\[1mm]
0,
& x\notin V_j,
\end{cases}
\]
so that, by definition of the flux,
\[
\frac{\operatorname{\mathfrak m_{t,\varepsilon}}}{\sqrt{\varepsilon}}
= \sum_{j\in J}
\int_{\mathbb{B}_R}
(\zeta_{\varepsilon,s,t}^j)_{\#}
\big(
F_{j,s}[\rho_j]\operatorname{vol}_M
\big)
\mathop{}\mathopen{}\mathrm{d} s.
\]
By \eqref{eq: symmetry of the Gaussian}, \(\int_{\mathbb{B}_R}F_{j,s}[\rho_j]\mathop{}\mathopen{}\mathrm{d} s=0\). Subtracting this in each term, we obtain
\begin{equation}
\label{eq: flow-decomposition}
\frac{\operatorname{\mathfrak m_{t,\varepsilon}}}{\sqrt{\varepsilon}}
=\sum_{j\in J}
\int_{\mathbb{B}_R}
\left((\zeta_{\varepsilon,s,t}^j)_{\#}-\operatorname{Id}\right)\left(
F_{j,s}[\rho_j]\operatorname{vol}_M
\right)
\mathop{}\mathopen{}\mathrm{d} s
=\sum_{j\in J}\mathbf{I}_{t,\varepsilon}^j[\rho_j],
\end{equation}
where, for \(f\in L^1(V_j)\),
\[
\mathbf{I}_{t,\varepsilon}^j[f]
\stackrel{\text{def.}}{=}
\int_{\mathbb{B}_R}
\left((\zeta_{\varepsilon,s,t}^j)_{\#}-\operatorname{Id}\right)\left(
F_{j,s}[f]\operatorname{vol}_M
\right)
\mathop{}\mathopen{}\mathrm{d} s.
\]

\textbf{Step 4. Estimate of the displacement term.} Fix \(j\in J\). We estimate the total variation of \(\mathbf{I}_{t,\varepsilon}^j[f]\) in two ways.

\emph{(a) For \(f\in L^1(V_j)\).} Since the push-forward operation does not increase the total variation and \(|A(z)s|\leq|n(z)s|=|s|\), \eqref{eq: gaussian-moments} gives
\begin{align*}
\|\mathbf{I}_{t,\varepsilon}^j[f]\|_{\mathrm{TV}}
&\leq 2\int_{\mathbb{B}_R}\|F_{j,s}[f]\|_{L^1(V_j)}\mathop{}\mathopen{}\mathrm{d} s
\\
&\leq 2\int_{V_j}|f(x)|\int_{\mathbb{B}_R}|s|K_j(x,s)\mathop{}\mathopen{}\mathrm{d} s\mathop{}\mathopen{}\mathrm{d}\operatorname{vol}_M(x)
\leq 2M_1\|f\|_{L^1(V_j)}.
\end{align*}

\emph{(b) For \(f\in C_c^1(V_j)\) supported in a fixed compact set \(S\subseteq V_j\).} Write \(F_s\stackrel{\text{def.}}{=} F_{j,s}[f]\). Fix \(t\in[0,1]\) and \(s\in\mathbb{B}_R\), and write \(\zeta\stackrel{\text{def.}}{=}\zeta_{\varepsilon,s,t}^j\), \(\kappa\stackrel{\text{def.}}{=}\zeta^{-1}\) and \(W\stackrel{\text{def.}}{=}\zeta(V_j)\). Since \(|\zeta(x)-x|\leq\sqrt\varepsilon R\),
we may choose \(\varepsilon>0\) sufficiently small, depending only on \(S\) (and not on \(f\), \(s\) and \(t\)), so that
\[
S\Subset W
\qquad\text{and}\qquad
\zeta(S)\Subset V_j.
\]
By the area formula, the density of \(\zeta_{\#}
(F_s\operatorname{vol}_M)\) is
\(F_s\circ\kappa\, \mathcal J_{\kappa}\mathbf{1}_{W}\), and, since \(\operatorname{spt}(F_s)\subseteq S\), the above inclusions show that \(F_s\circ\kappa\,\mathbf 1_{W}\) and \(F_s\) are both supported in \(W\cap V_j\). Hence
\begin{align*}
\big\|
\zeta_{\#}
(F_s\operatorname{vol}_M)
-
F_s\operatorname{vol}_M
\big\|_{\mathrm{TV}}
&\leq\|\mathcal J_{\kappa}-1\|_{L^\infty(W)}
\int_{W}
|F_s\circ\kappa|
\mathop{}\mathopen{}\mathrm{d} \operatorname{vol}_M
\\
&\quad+\int_{W\cap V_j }
|F_s\circ\kappa-F_s|\mathop{}\mathopen{}\mathrm{d}\operatorname{vol}_M.
\end{align*}
By \Cref{lemma: C^1 diffeo}, applied with \(\tau\stackrel{\text{def.}}{=} t\sqrt\varepsilon|s|L_j\) and \(f\stackrel{\text{def.}}{=} A_js/(|s|L_j)\), where \(L_j\) is a Lipschitz constant of \(A_j\) on the convex set \(V_j\) (recall that \(n\) is Lipschitz and \(\alpha_j\) is \(C^{1,1}\)), we have, for \(\varepsilon\) small enough, \(\|\mathcal J_{\kappa}-1\|_{L^\infty(W)}+\|\mathcal J_{\zeta}-1\|_{L^\infty(V_j)}\leq C\sqrt{\varepsilon}|s|\), and in particular \(1/2\leq\mathcal J_\kappa,\mathcal J_\zeta\leq2\) a.e. Since, by the area formula (change of variables \(y=\kappa(x)\)),
\[
\int_W|F_s\circ\kappa|\mathop{}\mathopen{}\mathrm{d}\operatorname{vol}_M
\leq2\int_W|F_s\circ\kappa|\,\mathcal J_\kappa\mathop{}\mathopen{}\mathrm{d}\operatorname{vol}_M
=2\|F_s\|_{L^1(V_j)},
\]
the first term is at most \(C\sqrt\varepsilon|s|\,\|F_s\|_{L^1(V_j)}\). For the second term, recall that \(F_s\) is defined on \(M\) and vanishes outside \(V_j\). By the area formula (change of variables \(x=\zeta(y)\)),
\[
\int_{W\cap V_j}|F_s\circ\kappa-F_s|\mathop{}\mathopen{}\mathrm{d}\operatorname{vol}_M
\leq2\int_{V_j}|F_s\circ\zeta-F_s|\mathop{}\mathopen{}\mathrm{d}\operatorname{vol}_M
\leq4\sqrt\varepsilon|s|\,\|\nabla F_s\|_{L^1(V_j)}.
\]
To prove the last inequality, assume first that \(F_s\) is \(C^1\). Since \(u\mapsto\zeta^j_{\varepsilon,s,ut}(y)=y+ut\sqrt\varepsilon A_j(y)s\) parametrizes the segment from \(y\) to \(\zeta(y)\) and \(|A_j(y)s|\leq|s|\), we have
\[
|F_s(\zeta(y))-F_s(y)|\leq\sqrt\varepsilon|s|\int_0^1\bigl|\nabla F_s\bigl(\zeta^j_{\varepsilon,s,ut}(y)\bigr)\bigr|\mathop{}\mathopen{}\mathrm{d} u,
\]
and we conclude by the area formula (change of variables \(x=\zeta^j_{\varepsilon,s,ut}(y)\)), since the inverse of \(\zeta^j_{\varepsilon,s,ut}\) has Jacobian at most \(2\) by \Cref{lemma: C^1 diffeo} (applied with \(ut\) in place of \(t\)). In general, \(F_s\) is only Lipschitz on \(M\), since \(A_j\) and \(K_j(\cdot,s)\) are Lipschitz on \(V_j\) (see below) and \(f\) has compact support in \(V_j\). We then apply the above to mollifications of \(F_s\), which converge to \(F_s\) in \(W^{1,1}(M)\), and pass to the limit, using that \(\int_{V_j}|g\circ\zeta|\mathop{}\mathopen{}\mathrm{d}\operatorname{vol}_M\leq2\|g\|_{L^1(M)}\) for \(g\in L^1(M)\), since \(\mathcal J_\kappa\leq2\). Altogether,
\[
\big\|
\zeta_{\#}
(F_s\operatorname{vol}_M)
-
F_s\operatorname{vol}_M
\big\|_{\mathrm{TV}}
\leq
C\sqrt{\varepsilon}|s|
\left(
\|F_s\|_{L^1(V_j)}
+
\|\nabla F_s\|_{L^1(V_j)}
\right).
\]
It remains to bound the \(L^1\) norms of \(F_s\) and \(\nabla F_s\). By \eqref{eq: normal-ellipticity} and since \(Z_R\geq c\), we have \(K_j(x,s)\leq c^{-1}e^{-\lambda|s|^2/2}\). Moreover, \(x\mapstoH_{\alpha_j(x)}E\) is Lipschitz (since \(E\in C^{2,1}\), \(n\) is Lipschitz and \(\alpha_j\) is \(C^{1,1}\)), hence so are \(x\mapsto Z_R(\alpha_j(x))\) and \(K_j(\cdot,s)\), and differentiating a.e.\
\(K_j(x,s)=\mathbf1_{\mathbb{B}_R}(s)\,e^{-H_{\alpha_j(x)}E(s,s)/2}/Z_R(\alpha_j(x))\) with respect to \(x\) gives \(|\nabla_xK_j(x,s)|\leq C(1+|s|^2)e^{-\lambda|s|^2/2}\) for a.e.\ \(x\in V_j\). Since \(F_s=f\,K_j(\cdot,s)\,A_js\), with \(|A_js|\leq|s|\) and \(A_j\) Lipschitz, the product rule yields
\[
\|F_s\|_{L^1(V_j)}
\leq
C e^{-\lambda|s|^2/2}
|s|\|f\|_{L^1(V_j)},
\]
\[
\|\nabla F_s\|_{L^1(V_j)}
\leq
C e^{-\lambda|s|^2/2}
\left[
|s|\|\nabla f\|_{L^1(V_j)}
+
(|s|+|s|^3)\|f\|_{L^1(V_j)}
\right].
\]
Integrating with respect to \(s\in\mathbb{B}_R\), we obtain, uniformly in \(t\in[0,1]\),
\[
\|\mathbf{I}_{t,\varepsilon}^j[f]\|_{\mathrm{TV}}
\leq
C\sqrt{\varepsilon} (M_2+M_4)
\left(
\|f\|_{L^1(V_j)}
+
\|\nabla f\|_{L^1(V_j)}
\right),
\]
where \(M_2\) and \(M_4\) are defined in \eqref{eq: gaussian-moments}.

\emph{Conclusion.} Since \(\chi_j\) has compact support in \(U_j\), \(\rho_j\) vanishes outside the compact set \(\operatorname{\mathrm{proj}}_M(\operatorname{spt}\chi_j)\subseteq V_j\). By mollification, there exist a compact set \(S_j\subseteq V_j\) and a sequence \((\rho_j^{(k)})_{k\in\mathbb{N}}\) in \(C_c^1(V_j)\), all supported in \(S_j\), such that
\(\|\rho_j-\rho_j^{(k)}\|_{L^1(V_j)}\to0\) as \(k\to\infty\). Applying (b) with \(S=S_j\), there exists \(\varepsilon_0>0\), independent of \(k\), such that, for \(0<\varepsilon\leq\varepsilon_0\) and every \(k\in\mathbb{N}\), writing \(\mathbf{I}_{t,\varepsilon}^j[\rho_j]=\mathbf{I}_{t,\varepsilon}^j[\rho_j-\rho_j^{(k)}]+\mathbf{I}_{t,\varepsilon}^j[\rho_j^{(k)}]\), (a) and (b) give
\[
\sup_{t\in[0,1]}\|\mathbf{I}_{t,\varepsilon}^j[\rho_j]\|_{\mathrm{TV}}
\leq 2M_1\|\rho_j-\rho_j^{(k)}\|_{L^1(V_j)}
+
C\sqrt{\varepsilon}
\left(
\|\rho_j^{(k)}\|_{L^1(V_j)}
+
\|\nabla \rho_j^{(k)}\|_{L^1(V_j)}
\right).
\]
For \(r>0\), set
\[
\omega_j(r)
\stackrel{\text{def.}}{=}
\inf_{k\geq1}
\left\{
2M_1\|\rho_j-\rho_j^{(k)}\|_{L^1(V_j)}
+
rC
\left(
\|\rho_j^{(k)}\|_{L^1(V_j)}
+
\|\nabla \rho_j^{(k)}\|_{L^1(V_j)}
\right)
\right\},
\]
and \(\omega(r)\stackrel{\text{def.}}{=}\sum_{j\in J}\omega_j(r)\).
Since \(\rho_j^{(k)}\to\rho_j\) in \(L^1(V_j)\), we have
\(\omega(r)\to0\) as \(r\to 0\): one first fixes \(k\) sufficiently large so that the first
term is arbitrarily small, and then lets \(r\to0\).
Combining this with \eqref{eq: flow-decomposition} yields, for \(0<\varepsilon\leq\varepsilon_0\),
\[
\sup_{t\in[0,1]}
\frac{\|\operatorname{\mathfrak m_{t,\varepsilon}}\|_{\mathrm{TV}}}
{\sqrt{\varepsilon}}
\leq \sum_{j\in J} \sup_{t\in[0,1]} \|\mathbf{I}_{t,\varepsilon}^j[\rho_j]\|_{\mathrm{TV}} \leq
\omega(\sqrt{\varepsilon})
=o(1).
\]

\textbf{Step 5. Benamou--Brenier estimate.} Recall from Step~2 and \eqref{eq: interpolation-charts} that
\begin{align*}
\operatorname{\mathfrak m_{t,\varepsilon}} &= \sqrt{\varepsilon}\sum_{j\in J} \int_{\mathbb{B}_R} (\zeta_{\varepsilon,s,t}^j)_{\#}\left(\rho_jK_j(\cdot,s)A_js\, \operatorname{vol}_M\right) \mathop{}\mathopen{}\mathrm{d} s,
\\
\mu_{t,\varepsilon}&=\sum_{j\in J}\int_{\mathbb{B}_R}(\zeta_{\varepsilon,s,t}^j)_{\#}(\rho_jK_j(\cdot,s)\operatorname{vol}_M)\mathop{}\mathopen{}\mathrm{d} s.
\end{align*}
Since \(|A_j(x)s|\leq|n(\alpha_j(x))s|=|s|\leq R\), we get \(|\operatorname{\mathfrak m_{t,\varepsilon}}|\leq\sqrt\varepsilon R\,\mu_{t,\varepsilon}\). Thus \(\operatorname{\mathfrak m_{t,\varepsilon}}\ll\mu_{t,\varepsilon}\), and the velocity field
\[
v_{t,\varepsilon}
\stackrel{\text{def.}}{=}\frac{\mathop{}\mathopen{}\mathrm{d} \operatorname{\mathfrak m_{t,\varepsilon}}}{\mathop{}\mathopen{}\mathrm{d}\mu_{t,\varepsilon}}\in L^\infty(\mu_{t,\varepsilon};TM)
\quad\text{satisfies}\quad |v_{t,\varepsilon}|\le\sqrt\varepsilon R
\quad\mu_{t,\varepsilon}\text{-a.e.}
\]
Since \((\mu_{t,\varepsilon},v_{t,\varepsilon})\) satisfies the
continuity equation, with \(\mu_{0,\varepsilon}=\mu\) and \(\mu_{1,\varepsilon}=\widetilde\mu_\varepsilon\), the Benamou--Brenier formula (see, e.g., \cite{santambrogioOptimalTransportApplied2015}) yields
\begin{align*}
W_2^2(\mu,\widetilde\mu_\varepsilon)
&\leq\int_0^1\int_M |v_{t,\varepsilon}|^2
\,\mathop{}\mathopen{}\mathrm{d}\mu_{t,\varepsilon}\mathop{}\mathopen{}\mathrm{d} t=\int_0^1\int_M |v_{t,\varepsilon}|\,\mathop{}\mathopen{}\mathrm{d}|\operatorname{\mathfrak m_{t,\varepsilon}}|\mathop{}\mathopen{}\mathrm{d} t
\\
&\le\sqrt\varepsilon R\sup_{t\in[0,1]}
\|\operatorname{\mathfrak m_{t,\varepsilon}}\|_{\mathrm{TV}}.
\end{align*}

By Step~4, \(\sup_{t\in[0,1]}\|\operatorname{\mathfrak m_{t,\varepsilon}}\|_{\mathrm{TV}}\leq\sqrt\varepsilon\,\omega(\sqrt\varepsilon)\) for \(0<\varepsilon\leq\varepsilon_0\), hence
\[
W_2^2(\mu,\widetilde\mu_\varepsilon)
\leq
\varepsilon R\,\omega(\sqrt{\varepsilon}).
\]
Since \(\omega(r)\to0\) as \(r\to0\), this gives \(W_2(\mu,\widetilde\mu_\varepsilon)=o_R(\sqrt{\varepsilon})\).

\label{thm: euclidean-Gibbs}
Under assumptions \ref{H1'}--\ref{H4'},
    \begin{equation}
        \operatorname{\mathbb{P}_\varepsilon} \xrightharpoonup[]{\ast}\mathbb{P}_0,
    \end{equation}
where \[\mathbb P_0 =\frac{1}{Z_0}
 (\det \operatorname{Hess}^\perp E)^{-1/2}
 \rho\mathbf{1}_{\mathcal K}\mathcal H^d_{|\Sigma} \quad  \text{and} \quad Z_0=\int_{\Sigma\cap \mathcal K}\frac{\rho_1(z_1)\rho_2(z_2)}
 {\sqrt{\det \operatorname{Hess}^\perp E(z)}}\,\mathop{}\mathopen{}\mathrm{d}\mathcal H^d(z). \]
Moreover, \(Z_\varepsilon=(2\pi\varepsilon)^{k/2}(Z_0+o(1))\).

Let \(r_0\) be as in \Cref{lemma: tubular vs regular neighborhood}. We fix \(r\in(0,r_0]\) such that the bounds of \Cref{lemma: quadratic-detachment} hold on \(\mathcal T_r\), and \(R>0\) so that \(R\sqrt\varepsilon<r\) for \(\varepsilon\) small enough. Let \(\phi\in C(\Omega)\) and introduce the unnormalized Gibbs measure
\[\mathop{}\mathopen{}\mathrm{d} \operatorname{\widetilde{\mathbb{P}}_\varepsilon}= (2\pi\varepsilon)^{-k/2} \exp\left(-\frac{E}{\varepsilon}\right)\mathop{}\mathopen{}\mathrm{d} \mu^\otimes,\]
so that \(\operatorname{\mathbb{P}_\varepsilon}=\operatorname{\widetilde{\mathbb{P}}_\varepsilon}/\operatorname{\widetilde{\mathbb{P}}_\varepsilon}(\Omega)\). We decompose \(\Omega\) as
\begin{align*}
\int_\Omega \phi\mathop{}\mathopen{}\mathrm{d}\operatorname{\widetilde{\mathbb{P}}_\varepsilon}
&=
\int_{\Sigma_{R\sqrt{\varepsilon}}}\phi\mathop{}\mathopen{}\mathrm{d}\operatorname{\widetilde{\mathbb{P}}_\varepsilon}
+
\int_{\Sigma_{r}\setminus \Sigma_{R\sqrt{\varepsilon}}}
\phi\mathop{}\mathopen{}\mathrm{d}\operatorname{\widetilde{\mathbb{P}}_\varepsilon}
+
\int_{\Omega\setminus\Sigma_{r}}
\phi\mathop{}\mathopen{}\mathrm{d}\operatorname{\widetilde{\mathbb{P}}_\varepsilon}
\\
&=\int_{\mathcal T_{R\sqrt{\varepsilon}}}\phi\mathop{}\mathopen{}\mathrm{d}\operatorname{\widetilde{\mathbb{P}}_\varepsilon}
+
\int_{\mathcal T_{r}\setminus \mathcal T_{R\sqrt{\varepsilon}}}
\phi\mathop{}\mathopen{}\mathrm{d}\operatorname{\widetilde{\mathbb{P}}_\varepsilon}
+
\int_{\Omega\setminus \Sigma_{r}}
\phi\mathop{}\mathopen{}\mathrm{d}\operatorname{\widetilde{\mathbb{P}}_\varepsilon}
\\
&\stackrel{\text{def.}}{=}
I_{1,\varepsilon,R}(\phi)
+
I_{2,\varepsilon,R}(\phi)
+
I_{3,\varepsilon}(\phi),
\end{align*}
where, for the second equality, we used that \(\operatorname{\widetilde{\mathbb{P}}_\varepsilon}\) is supported on \(\mathcal K\) and that \(\mathcal K\cap\Sigma_\rho=\mathcal K\cap\mathcal T_\rho\) for \(0<\rho\leq r\), by \Cref{lemma: tubular vs regular neighborhood} and since \(\mathcal T_\rho\subset\Sigma_\rho\). We analyze these three terms separately.

\textbf{Step 1. Estimate on \(\mathcal T_{R\sqrt{\varepsilon}}\).} Using the tubular coordinates induced by \(\Phi\), we write \(E(z,s)\) for \(E(\Phi(z,s))\) and define
\[
a(z,s)
\stackrel{\text{def.}}{=}
\phi\bigl(\Phi(z,s)\bigr)
\rho(\Phi(z,s))
\mathcal J_{\Phi}(z,s)\mathbf{1}_{\mathcal K}(\Phi(z,s)),
\]
for \(\mathcal H^{d}\otimes \mathcal L^k\)-a.e. \((z,s)\in(\Sigma\cap\omega)\times \mathbb{B}_{r}\). Note that \(|a|\leq\beta^2\|\phi\|_\infty C_J\), where \(C_J\) bounds \(\mathcal J_\Phi\) on \((\Sigma\cap\overline\omega)\times\mathbb{B}_r\). By the area formula \eqref{eq: tube-area-formula},
\[
I_{1,\varepsilon,R}(\phi)
=
(2\pi\varepsilon)^{-k/2}
\int_{\Sigma\cap\omega}
\int_{\mathbb{B}_{R\sqrt\varepsilon}}
e^{-E(z,s)/\varepsilon}
a(z,s)\mathop{}\mathopen{}\mathrm{d} s \mathop{}\mathopen{}\mathrm{d} \mathcal H^d_{|\Sigma}(z).
\]
Since \(E(z)=0\) and \(\nabla E(z)=0\) for \(z\in\Sigma\), and since \(E\in C^{2,1}\), we have
\[ E(z,s) = \frac12 H_{z}E(s,s) + \mathcal R(z,s),
\qquad
|\mathcal R(z,s)|\leq C|s|^3 \quad \text{for all } (z,s)\in (\Sigma\cap \overline\omega)\times \mathbb{B}_r.
\]
Performing the change of variables \(s=\sqrt{\varepsilon}\,\eta\), \(\mathop{}\mathopen{}\mathrm{d} s=\varepsilon^{k/2}\mathop{}\mathopen{}\mathrm{d} \eta\), and then relabeling the normal variable, we obtain
\begin{equation}
\label{eq: I1-after-rescaling}
I_{1,\varepsilon,R}(\phi)
=(2\pi)^{-k/2}
\int_{\Sigma\cap\omega}
\int_{\mathbb{B}_R}
e^{
-\frac{1}{2}
H_{z}E(s,s)
-\frac{1}{\varepsilon}\mathcal R(z,\sqrt{\varepsilon }s)}
a(z,\sqrt{\varepsilon }s)\mathop{}\mathopen{}\mathrm{d} s\mathop{}\mathopen{}\mathrm{d} \mathcal H^d_{|\Sigma}(z).
\end{equation}
As \(\varepsilon\to0\), we have \(|\mathcal R(z,\sqrt\varepsilon s)|/\varepsilon\leq C\sqrt\varepsilon|s|^3\to0\) and \(\mathcal J_\Phi(z,\sqrt\varepsilon s)\to\mathcal J_\Phi(z,0)=1\) by \Cref{lemma: determinant of Phi}. Moreover, \(\Phi(z,\sqrt\varepsilon s)\to z\) and \(\mathbf 1_{\mathcal K}\) is locally constant on \(\mathbb{R}^{2d}\setminus\partial\mathcal K\), so that, \(\rho\) being continuous on \(\mathcal K\), \((\rho\mathbf 1_{\mathcal K})(\Phi(z,\sqrt\varepsilon s))\to(\rho\mathbf 1_{\mathcal K})(z)\) for every \(z\in\Sigma\setminus\partial\mathcal K\); since \(\mathcal H^d(\Sigma\cap\partial\mathcal K)=0\), we get \(a(z,\sqrt\varepsilon s)\to\phi(z)\rho(z)\mathbf 1_{\mathcal K}(z)\) for \(\mathcal H^d\otimes\mathcal L^k\)-a.e.\ \((z,s)\in(\Sigma\cap\omega)\times\mathbb{B}_R\). Since the integrand of \eqref{eq: I1-after-rescaling} is bounded by \(e^{C\sqrt\varepsilon R^3}\beta^2\|\phi\|_\infty C_J\leq2\beta^2\|\phi\|_\infty C_J\) for \(\varepsilon\) small enough, and \(\mathcal H^d(\Sigma\cap\omega)\) is finite, the dominated convergence theorem gives
\[
\lim_{\varepsilon\to 0}I_{1,\varepsilon,R}(\phi)
=(2\pi)^{-k/2}\int_{\Sigma\cap\mathcal K}\phi(z)\rho(z)\int_{\mathbb{B}_R} e^{-H_{z}E(s,s)/2}\mathop{}\mathopen{}\mathrm{d} s\mathop{}\mathopen{}\mathrm{d}\mathcal H^d_{|\Sigma}(z).
\]
Next, since \((2\pi)^{-k/2}\int_{\mathbb{R}^k}e^{-H_{z}E(s,s)/2}\mathop{}\mathopen{}\mathrm{d} s=\bigl(\detH_{z}E\bigr)^{-1/2}\), the dominated convergence theorem gives
\[
\lim_{R\to +\infty} \lim_{\varepsilon \to 0}I_{1 ,\varepsilon , R}(\phi)=\int_{\Sigma\cap\mathcal K}\phi(z)\bigl(\det H_{z}E\bigr)^{-1/2}\rho(z)\mathop{}\mathopen{}\mathrm{d} \mathcal H^d_{|\Sigma}(z).
\]

\textbf{Step 2. Estimate on \(\mathcal T_{r}\setminus  \mathcal T_{R\sqrt{\varepsilon}}\).} As in Step~1, the area formula and the change of variables \(s=\sqrt\varepsilon\,\eta\) give
\[
\big|I_{2,\varepsilon,R}(\phi)\big|
\leq(2\pi)^{-k/2}\beta^2\|\phi\|_\infty C_J
\int_{\Sigma\cap\omega}\int_{R\leq|s|<r/\sqrt\varepsilon}
e^{-E(z,\sqrt\varepsilon s)/\varepsilon}\mathop{}\mathopen{}\mathrm{d} s\mathop{}\mathopen{}\mathrm{d}\mathcal H^d_{|\Sigma}(z).
\]
By \Cref{lemma: quadratic-detachment} and \eqref{eq: normal-distance}, \(E(z,\sqrt\varepsilon s)\geq\underline{C}\operatorname{dist}\bigl(\Phi(z,\sqrt\varepsilon s),\Sigma\bigr)^2=\underline C\varepsilon|s|^2\) for \(|s|<r/\sqrt\varepsilon\). Hence, uniformly in \(\varepsilon\),
\[
\big|I_{2,\varepsilon,R}(\phi)\big|
\leq(2\pi)^{-k/2}\beta^2\|\phi\|_\infty C_J\,\mathcal H^d(\Sigma\cap\omega)\int_{\mathbb{R}^k\setminus\mathbb{B}_R}e^{-\underline C|s|^2}\mathop{}\mathopen{}\mathrm{d} s
\xrightarrow[R\to+\infty]{}0,
\]
as the tail of an integrable Gaussian. This proves that the contribution of \(\mathcal T_r\setminus\mathcal T_{R\sqrt\varepsilon}\) is negligible.

\textbf{Step 3. Estimate on \(\Omega\setminus \Sigma_{r}\).}
If \(\mathcal K\setminus \Sigma_{r}= \emptyset\) there is nothing to do. Otherwise, \(\mathcal K\setminus\Sigma_r\) is a compact set which does not meet \(\Sigma\), so that \(E>0\) on it, and we denote
\[
\delta \stackrel{\text{def.}}{=}
\min_{\mathcal K\setminus\Sigma_r}E>0.
\]
Since \(\operatorname{\widetilde{\mathbb{P}}_\varepsilon}\) is supported on \(\mathcal K\) and \(\mu^\otimes(\mathcal K)=1\),
\[
\big|I_{3,\varepsilon}(\phi)\big|
\leq (2\pi\varepsilon)^{-k/2} \|\phi\|_{\infty}
e^{-\delta/\varepsilon}\xrightarrow[\varepsilon \to 0]{} 0.
\]

\textbf{Conclusion.} Set \(L(\phi)\stackrel{\text{def.}}{=}\int_{\Sigma\cap\mathcal K}\phi(z)\bigl(\det H_{z}E\bigr)^{-1/2}\rho(z)\mathop{}\mathopen{}\mathrm{d}\mathcal H^d_{|\Sigma}(z)\). Since \(\int_\Omega\phi\mathop{}\mathopen{}\mathrm{d}\operatorname{\widetilde{\mathbb{P}}_\varepsilon}\) does not depend on \(R\), Steps~1--3 give, for every \(R>0\),
\[
\limsup_{\varepsilon\to0}\left|\int_\Omega\phi\mathop{}\mathopen{}\mathrm{d}\operatorname{\widetilde{\mathbb{P}}_\varepsilon}-L(\phi)\right|
\leq\left|\lim_{\varepsilon\to0}I_{1,\varepsilon,R}(\phi)-L(\phi)\right|+\sup_{\varepsilon}\big|I_{2,\varepsilon,R}(\phi)\big|,
\]
and the right-hand side tends to \(0\) as \(R\to+\infty\). In other words,
\[
\operatorname{\widetilde{\mathbb{P}}_\varepsilon}
\xrightharpoonup[]{\ast}
\bigl(\det \operatorname{Hess}^\perp E\bigr)^{-1/2}
\rho\mathbf 1_{\mathcal K}
\mathcal H^d_{|\Sigma}.
\]
Taking \(\phi\equiv1\), we get \(\operatorname{\widetilde{\mathbb{P}}_\varepsilon}(\Omega)=(2\pi\varepsilon)^{-k/2}Z_\varepsilon\to Z_0\), which is the asymptotics of \(Z_\varepsilon\). Moreover, \(Z_0>0\): an optimal plan is concentrated on \(\Sigma\cap\mathcal K\), so that \(\mu_1\) is concentrated on \(\operatorname{\mathrm{proj}}_{M_1}(\Sigma\cap\mathcal K)\), and since \(\mu_1\) is absolutely continuous and \(\operatorname{\mathrm{proj}}_{M_1}\) is \(1\)-Lipschitz, \(0<\mathcal L^d(\operatorname{\mathrm{proj}}_{M_1}(\Sigma\cap\mathcal K))\leq\mathcal H^d(\Sigma\cap\mathcal K)\). Thus
\[\operatorname{\mathbb{P}_\varepsilon} = \frac{\operatorname{\widetilde{\mathbb{P}}_\varepsilon}}{\operatorname{\widetilde{\mathbb{P}}_\varepsilon}(\Omega)}
\xrightharpoonup[]{\ast}
\frac1{Z_0}
\bigl(\det \operatorname{Hess}^\perp E\bigr)^{-1/2}
\rho\mathbf1_{\mathcal K}
\mathcal H^d_{|\Sigma},
\]
which proves the claim.

\label{thm: euclidean-selection}
Assume the hypotheses \ref{H1'}--\ref{H4'} are satisfied and define
\[\mathcal F^{(0)}(\gamma)\stackrel{\text{def.}}{=}\int_{\Omega}c\mathop{}\mathopen{}\mathrm{d} \gamma+\chi_{\Pi(\mu_1,\mu_2)}(\gamma),
\qquad
\mathcal F_{\varepsilon}(\gamma)=\int_{\Omega}c\mathop{}\mathopen{}\mathrm{d} \gamma+\varepsilon\operatorname{Ent}(\gamma|\mu_1\otimes\mu_2)+\chi_{\Pi(\mu_1,\mu_2)}(\gamma).\]
Then, with \(\mathbb P_0\) and \(Z_0\) given by \Cref{thm: euclidean-Gibbs},
\begin{equation}
\label{eq: gamma-expansion-R}
 \mathcal F_\varepsilon-\frac{k}{2}\varepsilon\log(1/\varepsilon)
 \stackrel{\Gamma}{=}
 \mathcal F^{(0)}+\varepsilon\Bigl(
 \operatorname{Ent}\left(\cdot\,|\,\mathbb P_0\right)+\chi_{\Pi(\mu_1,\mu_2)}(\cdot)
 -\log Z_0-\frac{k}{2}\log(2\pi)
 \Bigr)+o(\varepsilon).
\end{equation}
Moreover, the following asymptotics of the energy holds
\begin{equation}
    \label{eq: energy-expansion-R}
    \min\mathcal{F}_\varepsilon=\min \mathcal F^{(0)}+\dfrac{k}{2}\varepsilon\log(1/\varepsilon)+\varepsilon C_0+o(\varepsilon),
\end{equation}
where \(C_0\stackrel{\text{def.}}{=}  \min_{\gamma\in\Pi(\mu_1,\mu_2)}  \operatorname{Ent}(\gamma\,|\,\mathbb P_0)-\log Z_0-\frac{k}{2}\log(2\pi)\), and the minimizer of \(\mathcal F_\varepsilon\) converges weakly to the unique minimizer of \(\operatorname{Ent}(\cdot\,|\,\mathbb P_0)\) on \(\Pi(\mu_1,\mu_2)\).
